 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    # The horizontal 1-line is the baseline. Each marker grows upward;
    # 2 has four cells above the baseline and 8 has three.
    baseline = next((r for r, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if baseline is None:
        return out
    for c, value in enumerate(grid[baseline]):
        if value in (2, 8):
            height_above = 4 if value == 2 else 3
            top = max(0, baseline - height_above)
            out[top][c] = value
            for r in range(top + 1, baseline):
                out[r][c] = 1
    return out
